// Sound effects + the narrator voice.
//
// Voice: recorded British-English female clips (generated by scripts/gen_audio.py)
// are played from /audio when they exist. Anything without a clip falls back to the device's own voice
// (preferring a British female one), so nothing ever goes silent.
import { gstore } from './store.js';

export const prefs = { sound: gstore.get('sound', true) };
export function setSound(on) {
  prefs.sound = on;
  gstore.set('sound', on);
  if (!on) stopSpeaking();
}

// ---------------------------------------------------------------- sound effects
let ctx;
function audio() {
  try {
    ctx ||= new (window.AudioContext || window.webkitAudioContext)();
    if (ctx.state === 'suspended') ctx.resume();
  } catch { /* no audio available */ }
  return ctx;
}

const SILENT_WAV = 'data:audio/wav;base64,UklGRiQAAABXQVZFZm10IBAAAAABAAEAESsAACJWAAACABAAZGF0YQAAAAA=';

/** iOS only allows sound/speech after a tap — unlock everything on the very first touch. */
export function unlockOnFirstTouch() {
  const unlock = () => {
    const a = audio();
    if (a) {
      const b = a.createBuffer(1, 1, 22050);
      const s = a.createBufferSource();
      s.buffer = b; s.connect(a.destination); s.start(0);
    }
    try {
      voiceEl.src = SILENT_WAV;
      voiceEl.play().then(() => voiceEl.pause()).catch(() => {});
    } catch { /* ignore */ }
    try {
      const u = new SpeechSynthesisUtterance(' ');
      u.volume = 0;
      window.speechSynthesis?.speak(u);
    } catch { /* ignore */ }
    window.removeEventListener('pointerdown', unlock, true);
  };
  window.addEventListener('pointerdown', unlock, true);
}

function note(freq, start, dur, type = 'sine', vol = 0.18) {
  const a = audio();
  if (!a) return;
  const t = a.currentTime + start;
  const o = a.createOscillator();
  const g = a.createGain();
  o.type = type; o.frequency.value = freq;
  g.gain.setValueAtTime(0.0001, t);
  g.gain.exponentialRampToValueAtTime(vol, t + 0.02);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  o.connect(g); g.connect(a.destination);
  o.start(t); o.stop(t + dur + 0.05);
}
export function ding() {
  if (!prefs.sound) return;
  note(784, 0, 0.18, 'triangle');
  note(1175, 0.09, 0.28, 'triangle');
}
export function cheer() {
  if (!prefs.sound) return;
  [523, 659, 784, 1047].forEach((f, i) => note(f, i * 0.12, 0.3, 'triangle', 0.2));
  note(1568, 0.5, 0.5, 'sine', 0.15);
}
export function oops() {
  if (!prefs.sound) return;
  note(330, 0, 0.15, 'sine', 0.12);
  note(262, 0.12, 0.22, 'sine', 0.12);
}

// ---------------------------------------------------------------- recorded voice clips
const AUDIO_DIR = '/audio/';
let clips = null; // key -> {f: file, w: [word start ms]}
let loading = null;
export const missingClips = new Set(); // phrases that had no recording (handy when testing)
if (typeof window !== 'undefined') window.__missingClips = missingClips;

function loadClips() {
  loading ||= fetch(`${AUDIO_DIR}index.json`)
    .then((r) => (r.ok ? r.json() : {}))
    .then((j) => { clips = j.clips || {}; })
    .catch(() => { clips = {}; });
  return loading;
}
if (typeof window !== 'undefined') loadClips();

/** How many recorded phrases are available (0 until the clips have been generated). */
export async function clipCount() { await loadClips(); return Object.keys(clips).length; }
export async function clipFiles() { await loadClips(); return Object.values(clips).map((c) => c.f); }

const keyOf = (t) => t.toLowerCase().replace(/\s+/g, ' ').trim();
// A part is a string, or {k, t}: a clip key plus the text to say if there is no clip.
const toPart = (x) => (typeof x === 'string' ? { key: keyOf(x), text: x } : { key: x.k, text: x.t });
const toParts = (p) => (Array.isArray(p) ? p : [p]).filter((x) => x && (typeof x === 'string' ? x.trim() : x.t)).map(toPart);

const voiceEl = typeof Audio !== 'undefined' ? new Audio() : null;
let token = 0; // bumps whenever speech is cancelled so old callbacks go quiet
let raf = 0;

export function stopSpeaking() {
  token++;
  cancelAnimationFrame(raf);
  try { if (voiceEl) { voiceEl.onended = null; voiceEl.onerror = null; voiceEl.pause(); } } catch { /* ignore */ }
  try { window.speechSynthesis?.cancel(); } catch { /* ignore */ }
}

const clampRate = (r) => Math.max(0.5, Math.min(1.6, r / 0.85));

function playClip(c, o, mine, done) {
  let finished = false;
  const fin = () => {
    if (finished || mine !== token) return;
    finished = true;
    cancelAnimationFrame(raf);
    done();
  };
  voiceEl.onended = fin;
  voiceEl.onerror = fin;
  voiceEl.src = AUDIO_DIR + c.f;
  voiceEl.playbackRate = clampRate(o.rate ?? 0.85) * (o.pitch > 1.3 ? 1.25 : 1);
  const keepPitch = !(o.pitch > 1.3); // silly high-pitched sound effects: let the pitch go up
  voiceEl.preservesPitch = keepPitch;
  voiceEl.webkitPreservesPitch = keepPitch;
  if (o.onWord && c.w) {
    let last = -1;
    const tick = () => {
      if (mine !== token || finished) return;
      const t = voiceEl.currentTime * 1000;
      let idx = -1;
      for (let i = 0; i < c.w.length; i++) if (c.w[i] <= t) idx = i;
      if (idx !== last) { last = idx; o.onWord(idx); }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
  }
  voiceEl.play().catch(fin);
}

// the device's own voice: prefer a British female voice
let voice;
function pickVoice() {
  if (voice) return voice;
  const vs = window.speechSynthesis?.getVoices?.() || [];
  const gb = vs.filter((v) => /^en[-_]GB/i.test(v.lang));
  voice =
    gb.find((v) => /sonia|libby|maisie|serena|kate|martha|stephanie|female/i.test(v.name)) ||
    gb[0] ||
    vs.find((v) => /samantha|ava|allison|karen|moira|google us english/i.test(v.name) && /^en/i.test(v.lang)) ||
    vs.find((v) => /^en/i.test(v.lang));
  return voice;
}
window.speechSynthesis?.addEventListener?.('voiceschanged', () => { voice = null; });

function makeUtterance(text, { rate = 0.85, pitch = 1.15 } = {}) {
  const u = new SpeechSynthesisUtterance(text);
  u.lang = 'en-GB';
  u.rate = rate;
  u.pitch = pitch;
  const v = pickVoice();
  if (v) u.voice = v;
  return u;
}

function browserSay(text, o, mine, done) {
  if (!window.speechSynthesis) { done(); return; }
  const u = makeUtterance(text, { rate: o.rate, pitch: o.pitch });
  const fin = () => { if (mine === token) done(); };
  u.onend = fin;
  u.onerror = fin;
  window.speechSynthesis.speak(u);
}

function playOne(part, o, mine, done) {
  const c = clips?.[part.key];
  if (c && voiceEl) { playClip(c, o, mine, done); return; }
  if (clips && Object.keys(clips).length) missingClips.add(part.text);
  browserSay(part.text, o, mine, done);
}

/** Run `fn` once the clip list has loaded (so the first sentence on app start still gets the recorded voice). */
function whenReady(mine, fn) {
  if (clips) fn();
  else loadClips().then(() => { if (mine === token) fn(); });
}

function playParts(parts, o, mine) {
  let i = 0;
  const next = () => {
    if (mine !== token) return;
    if (i >= parts.length) { o.onEnd?.(); return; }
    const idx = i++;
    o.onEach?.(idx);
    playOne(parts[idx], o, mine, () => setTimeout(next, o.gap ?? 40));
  };
  next();
}

/** Say something. `phrase` = string | {k,t} | a list of those (played one after another). */
export function speak(phrase, opts = {}) {
  if (!prefs.sound || !phrase) return;
  const parts = toParts(phrase);
  if (!parts.length) return;
  try {
    stopSpeaking();
    const mine = token;
    whenReady(mine, () => playParts(parts, opts, mine));
  } catch { /* ignore */ }
}

/** Say several chunks one after another with a small gap (used for "sound it out"). */
export function speakSeq(list, { rate = 0.6, gap = 420, onEach, onEnd, pitch } = {}) {
  if (!list?.length) { onEnd?.(); return; }
  stopSpeaking();
  const mine = token;
  whenReady(mine, () => playParts(toParts(list), { rate, gap, onEach, onEnd, pitch }, mine));
}

/**
 * Read text aloud and report which word is being spoken (for highlighting).
 * With a recorded clip the highlight follows the real word timings; otherwise the device voice's word
 * events are used, or an estimate (iPad Safari doesn't always send word boundaries).
 * `starts` = character offset where each word begins.
 */
export function speakSync(text, { rate = 0.8, starts = [], onWord, onEnd } = {}) {
  stopSpeaking();
  const mine = token;
  whenReady(mine, () => {
    const c = clips?.[keyOf(text)];
    if (c && voiceEl) {
      playClip(c, { rate, onWord }, mine, () => onEnd?.());
      return;
    }
    if (!window.speechSynthesis) { onEnd?.(); return; }
    if (clips && Object.keys(clips).length) missingClips.add(text);
    let gotBoundary = false;
    let finished = false;
    const timers = [];
    const finish = () => {
      if (finished || mine !== token) return;
      finished = true;
      timers.forEach(clearTimeout);
      onEnd?.();
    };
    const u = makeUtterance(text, { rate });
    u.onboundary = (e) => {
      if (mine !== token || (e.name && e.name !== 'word')) return;
      gotBoundary = true;
      let idx = 0;
      starts.forEach((st, i) => { if (st <= e.charIndex) idx = i; });
      onWord?.(idx);
    };
    u.onend = finish;
    u.onerror = finish;
    timers.push(setTimeout(() => {
      if (gotBoundary || mine !== token || finished) return;
      let t = 0;
      starts.forEach((st, i) => {
        const next = starts[i + 1] ?? text.length;
        timers.push(setTimeout(() => { if (mine === token && !finished) onWord?.(i); }, t));
        t += ((next - st) * 62 + 130) / rate / 0.8;
      });
    }, 700));
    window.speechSynthesis.speak(u);
  });
}
